// These tests use the existing authenticated private-D-Bus Actions router. No device.
fn creation_http_body()->serde_json::Value{serde_json::json!({"expected_revision":1,"nonce":"e".repeat(32),"name":"private-http-create","group_type":1,"expected_owner_uid":"fixture-user","members":[{"uid":"fixture-user","relation_type":257,"first":"explicit-first","second":"explicit-second","properties":[]}],"properties":[],"consent":true,"write_consent":true,"properties_read_consent":true})}
fn creation_http_private(body:&str){no_secrets(body);for hidden in ["private-http-create","811111111-922222222","explicit-first","explicit-second","single-relation","private-value","read_properties\":","body_hash","reply_hash",&"e".repeat(32)]{assert!(!body.contains(hidden));}}
#[tokio::test]
async fn group_create_http_auth_and_unknown_fields_do_not_mint_receipt_or_echo_input(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/groups/create";
    let(s,_,b)=account_request(&served,reqwest::Method::POST,path,Some(creation_http_body()),None).await;assert_eq!(s,StatusCode::UNAUTHORIZED);creation_http_private(&b);let cookie=authenticate(&served).await;
    for field in ["group_id","token","scope","accepted","creation_receipt","clear_unknown","callback"]{let mut v=creation_http_body();v[field]=serde_json::json!("private-value");let(s,h,b)=account_request(&served,reqwest::Method::POST,path,Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_store(&h);creation_http_private(&b);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn group_create_http_requires_explicit_strings_owner_exactly_once_and_bounded_converted_properties(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/groups/create";
    for mode in 0..12{let mut v=creation_http_body();let member=v["members"][0].clone();match mode{0=>v["members"]=serde_json::json!([]),1=>v["members"]=serde_json::json!([member,member]),2=>v["expected_owner_uid"]=serde_json::json!("other"),3=>{v["members"][0].as_object_mut().unwrap().remove("first");},4=>{v["members"][0].as_object_mut().unwrap().remove("second");},5=>v["members"][0]["relation_type"]=serde_json::json!(20),6=>v["properties"]=serde_json::json!([{"key":"Group.Org.Name","value":"override"}]),7=>v["properties"]=serde_json::json!([{"key":"Permission","value":1},{"key":"Group.Org.JoinAuth","value":"duplicate"}]),8=>v["members"][0]["properties"]=serde_json::json!([{"key":[0],"value":[1]}]),9=>{v["members"]=serde_json::json!([member,{"uid":"[phone:+12345@fixture.invalid]","relation_type":258,"first":"","second":""}]);},10=>v["members"][0]["relation_type"]=serde_json::json!(258),_=>v["name"]=serde_json::json!("x".repeat(65537))}
        let(s,h,b)=account_request(&served,reqwest::Method::POST,path,Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST,"mode {mode}");no_store(&h);creation_http_private(&b);
    }assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn group_create_http_stopped_and_invalid_policy_never_open_sdk_or_read_on_get(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");
    for grant in [serde_json::json!({"create":false,"read_properties":true}),serde_json::json!({"create":true,"ready":true})]{let mut c=relation_http_config(&cert.root);c["profile"]["group_creation"]=grant;let(s,h,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_store(&h);creation_http_private(&b);}
    let mut c=relation_http_config(&cert.root);c["profile"]["group_creation"]=serde_json::json!({"create":true});let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);let path=format!("/api/non-3gpp/accounts/{line}/groups/create");
    for mode in 0..4{let mut v=creation_http_body();if mode==0{v["consent"]=serde_json::json!(false);}if mode==1{v["write_consent"]=serde_json::json!(false);}if mode==2{v["expected_revision"]=serde_json::json!(2);}let(s,h,b)=account_request(&served,reqwest::Method::POST,&path,Some(v),Some(&cookie)).await;assert_eq!(s,match mode{0|1=>StatusCode::FORBIDDEN,2=>StatusCode::CONFLICT,_=>StatusCode::SERVICE_UNAVAILABLE});no_store(&h);creation_http_private(&b);}let(s,_,_)=account_request(&served,reqwest::Method::GET,&path,None,Some(&cookie)).await;assert_eq!(s,StatusCode::METHOD_NOT_ALLOWED);assert!(state.app.app_accounts.relation_write_history(&line,128).unwrap().is_empty());assert!(state.app.app_accounts.relation_intent_history(&line,128).unwrap().is_empty());assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");
}
#[tokio::test]
async fn group_create_http_current_write_then_separate_read_and_replay_without_group_or_second_packet(){Box::pin(async{
    use crate::connectivity::app_voice::providers::jegotrip as n;
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let listener=tokio::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&tokio_rustls::rustls::version::TLS13);
    let mut c=relation_http_config(&cert.root);c["profile"].as_object_mut().unwrap().remove("relation_updates");c["profile"]["group_creation"]=serde_json::json!({"create":true,"read_properties":true});let route=&mut c["profile"]["route"]["router_common"];route["reference"]=serde_json::json!(format!("Router:tls -h 127.0.0.1 -p {port} -ri 12001;"));route["anchors"][0]["port"]=serde_json::json!(port);
    let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);let prefix=format!("/api/non-3gpp/accounts/{line}");let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(n::relation_http_test_peer::serve_group_create(listener,server,state.app.database.clone(),line.clone(),rx)));
    let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/start"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::ACCEPTED);tokio::time::timeout(std::time::Duration::from_secs(6),async{while state.app.app_accounts.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await.unwrap();
    let path=format!("{prefix}/groups/create");let mut write_id=None;for fresh in [true,false]{let(s,h,b)=account_request(&served,reqwest::Method::POST,&path,Some(creation_http_body()),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);creation_http_private(&b);let v:serde_json::Value=serde_json::from_str(&b).unwrap();let w=&v["data"]["write"];assert_eq!(w["state"],"confirmed");assert_eq!(w["base_time"],"-9223372036854775808");assert_eq!(w["update_time"],"9223372036854775807");assert_eq!(w["management"],serde_json::json!({"operation":"create","properties":2}));let id=w["id"].as_i64().unwrap();if fresh{write_id=Some(id);}else{assert_eq!(write_id,Some(id));}assert_eq!(v["data"]["properties_read"],if fresh{serde_json::json!({"state":"observed","accepted":true,"properties":1})}else{serde_json::json!({"state":"not_attempted","accepted":null,"properties":null})});}
    let(s,h,b)=account_request(&served,reqwest::Method::GET,&format!("{prefix}/relation-writes?limit=128"),None,Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);creation_http_private(&b);assert!(!b.contains("properties_read"));assert_eq!(state.app.database.get_recent_app_events(Some(&line),128).unwrap().iter().filter(|e|e.event_type=="app_voice.group_created").count(),1);
    tx.send(()).unwrap();let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/stop"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);peer.await.unwrap();assert!(!state.app.app_accounts.get(&line,100).await.unwrap().io_cleanup_required);
}).await;}
